// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bytes memory data) public {
        uint256 bounded = bound(amount, 0, 1 ether);

        Reverter rev = new Reverter();

        vm.deal(address(this), bounded);
        (bool s, ) = address(c).call{value: bounded}("");
        require(s);

        bool ok;
        try c.sendMoney(address(rev), bounded, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
